   8	import "./app.css";
   9	
  10	/**
  11	 * The single MCP App bundle. It renders whatever `{title, blocks, actions}`
  12	 * view the host streams and routes each action through the standard MCP Apps
  13	 * bridge (`tools/call` or `ui/open-link`) — every interactive interaction is
  14	 * just a different view through this one bundle.
  15	 * All MCP-transport plumbing lives in `../_shared/host`.
  16	 */
  17	
  18	/** Sample view shown when opened standalone (dev/test, not embedded). */
  19	const DEV_MOCK: InteractionView = {
  20		version: 1,
  21		title: "Update agent support-triage",
  22		tone: "warning",
  23		blocks: [
  24			{
  25				type: "diff",
  26				fields: [
  27					{
  28						label: "description",
  29						before: "Answers support questions on request",
  30						after: "Triages #support and drafts replies every morning",
  31					},
  32				],
  33			},
  34		],
  35		actions: [
  36			{
  37				id: "review",
  38				label: "Review in Lobu",
  39				variant: "primary",
  40				icon: "external",
  41				terminal: false,
  42				href: "https://lobu.ai/example/runs/42",
  43			},
  44		],
  45	};
  46	
  47	function InteractionApp() {
  48		const {
  49			data,
  50			toolName,
  51			viewState,
  52			setViewState,
  53			callTool,
  54			openLink,
  55			lastResult,
  56			allowSpaHostedViews,
  57		} = useMcpApp<unknown>();
  58		const [pendingId, setPendingId] = useState<string | null>(null);
  59	
  60		// Host brokered the `tools/call`; the returned structured result replaces
  61		// the card on success, while errors simply re-enable the original action.
  62		useEffect(() => {
  63			if (!lastResult) return;
  64			setPendingId(null);
  65		}, [lastResult]);
  66	
  67		if (!data) {
  68			return <div className="p-2 text-xs text-muted-foreground">Loading…</div>;
  69		}
  70	
  71		const onAction = (action: InteractionAction) => {
  72			if (action.href) {
  73				void openLink(action.href);
  74				return;
  75			}
  76			if (!action.tool) return;
  77			if (action.terminal !== false) setPendingId(action.id);
  78			void callTool(action.tool, action.args ?? {});
  79		};
  80	
  81		return (
  82			<McpResultView
  83				value={data}
  84				toolName={toolName ?? undefined}
  85				viewState={viewState}
  86				onViewStateChange={setViewState}
  87				onAction={onAction}
  88				openLink={(href) => void openLink(href)}
  89				pendingId={pendingId}
  90				allowSpaHostedViews={allowSpaHostedViews}
  91			/>
  92		);
  93	}
  94	
  95	mountMcpApp({ devMock: DEV_MOCK, App: InteractionApp });
